// View: Rare events. Pick an event (festival, holiday, exam week, heavy rain), a day and a meal. Two models answer
// side by side: the forecast with the event applied, and a few hundred possible days generated by the rare event GAN.
// Choose which quantities to cook and approve the plan for this meal, or for several days and meals at once. An
// approved event plan is saved like any other plan, so the Service board, Plans, Forecast and Calendar all show it.
import { api } from "./api.js";
import { liquid, replay, setHTML } from "./fx.js";
import { icon } from "./icons.js";
import { notify, openPlan, state, subscribe, synced } from "./state.js";
import { SLOTS, cap, esc, fmt, planKind, shortDate, statusPill } from "./util.js";

const EVENT_ICON = { festival: "star", holiday: "sun", exam_week: "book", rain: "rain" };
const VERDICT = { covered: ["low", "Covered"], may_run_short: ["high", "May run short"], may_be_left_over: ["medium", "May be left over"], no_generated: ["", "No generated data"] };
const OPTIONS = [
  ["forecast", "Forecast with the event", "The forecast's recommendation (its 75th percentile) with the event applied."],
  ["generated_typical", "Generated typical day", "The middle of the generated days: less food, more risk of running short."],
  ["generated_high", "Generated busy day", "Nine in ten generated days need no more than this: the safest, with more left over."],
];
const signed = (v) => `${v > 0 ? "+" : v < 0 ? "-" : ""}${fmt(Math.abs(v))}`;
const kg = (v) => `${v >= 100 ? fmt(v) : v.toFixed(1)} kg`;

const SKELETON = `
  <header class="ev-top">
    <p class="eyebrow">${icon("bolt")}Rare events</p><h1 class="ev-title">Plan for a rare day</h1>
    <p class="ev-sub">Choose an event and a meal. The forecast with the event and the demand generated by the rare event model sit side by side,
      so you can see how differently such a day can turn out before you approve what to cook.</p>
  </header>
  <div class="ev-grid">
    <aside class="ev-controls glass">
      <h2>1. The event</h2>
      <div class="ev-types" id="ev-types" role="radiogroup" aria-label="Event"></div>
      <h2>2. The day and meal</h2>
      <div class="ev-field"><label for="ev-date">Day</label><input id="ev-date" type="date"></div>
      <div class="seg ev-slots" id="ev-slot" role="group" aria-label="Meal slot">${SLOTS.map((s) => `<button type="button" data-slot="${s}" aria-pressed="false">${cap(s)}</button>`).join("")}</div>
      <div class="ev-field"><label for="ev-att">Attendance change on top of the event</label>
        <input id="ev-att" type="range" min="-40" max="40" step="5" value="0"><div class="hint" id="ev-att-hint">No change</div></div>
      <h2>${icon("calendar")}Coming up</h2>
      <ul class="ev-upcoming" id="ev-upcoming"></ul>
      <p class="ev-gan" id="ev-gan"></p>
    </aside>
    <div class="ev-main">
      <div id="ev-error"></div>
      <section class="ev-head glass" id="ev-head" aria-live="polite"></section>
      <section class="ev-kpis" id="ev-kpis"></section>
      <section class="dk-card glass" aria-labelledby="ev-gen-t"><h2 id="ev-gen-t">${icon("spark")}Generated demand for the main dishes</h2>
        <p class="dk-panel-note" id="ev-gen-note"></p><div class="ev-hist" id="ev-hist"></div></section>
      <section class="dk-card glass" aria-labelledby="ev-dish-t"><h2 id="ev-dish-t">${icon("service")}Dish by dish</h2>
        <div class="tablewrap" id="ev-dishes"></div></section>
      <section class="dk-card glass" aria-labelledby="ev-ing-t"><h2 id="ev-ing-t">${icon("list")}Ingredients to have ready</h2><div id="ev-ing"></div></section>
      <section class="dk-card glass ev-approve" aria-labelledby="ev-ok-t"><h2 id="ev-ok-t">${icon("check")}Approve the event plan</h2>
        <div class="ev-options" id="ev-options" role="radiogroup" aria-label="Quantities to cook"></div>
        <div class="ev-approve-row" id="ev-approve-row"></div>
        <details class="ev-many"><summary>${icon("calendar")}Approve it for several days and meals at once</summary>
          <p class="dk-panel-note">For an exam week or a festival weekend: the same event and the same choice of quantities, worked out for each day and meal.</p>
          <div class="ev-many-row"><label for="ev-days">Days from the chosen day</label><input id="ev-days" type="number" min="1" max="14" value="5">
            <fieldset class="ev-many-slots"><legend>Meals</legend>${SLOTS.map((s) => `<label><input type="checkbox" value="${s}" checked>${cap(s)}</label>`).join("")}</fieldset>
            <button class="btn" type="button" id="ev-many-go">${icon("check")}Approve all of them</button></div></details>
      </section>
    </div>
  </div>`;

function histogram(r) {
  const h = r.generated.total?.histogram;
  if (!h?.length) return `<div class="empty"><strong>${esc(r.generated.note || "No generated data for this meal.")}</strong></div>`;
  const marks = [["Normal plan", r.normal.totals.recommended, "#8AA094"], ["Forecast with the event", r.plan.totals.recommended, "#C8432A"],
    ["Generated busy day", r.generated.total.p90, "#0F766E"]];
  const W = 760, H = 270, ml = 16, mr = 16, mt = 66, mb = 44;
  const lo = Math.min(h[0].lo, ...marks.map((m) => m[1])) * 0.97, hi = Math.max(h[h.length - 1].hi, ...marks.map((m) => m[1])) * 1.03;
  const x = (v) => ml + ((v - lo) / (hi - lo)) * (W - ml - mr);
  const top = Math.max(...h.map((b) => b.count)) || 1;
  const bars = h.map((b, i) => {
    const bh = (b.count / top) * (H - mt - mb);
    return `<rect class="pt" style="--i:${i}" x="${x(b.lo) + 1}" y="${H - mb - bh}" width="${Math.max(2, x(b.hi) - x(b.lo) - 2)}" height="${bh}" rx="4" fill="url(#evBar)"><title>${fmt(b.lo)} to ${fmt(b.hi)} portions: ${b.count} of ${r.generated.draws} generated days</title></rect>`;
  }).join("");
  // one label row per marker, anchored so it never leaves the chart
  const lines = marks.map(([label, v, c], i) => {
    const at = x(v), anchor = at < W * 0.25 ? "start" : at > W * 0.75 ? "end" : "middle";
    return `<line x1="${at}" x2="${at}" y1="${16 + i * 17}" y2="${H - mb}" stroke="${c}" stroke-width="2.5" stroke-dasharray="${i === 2 ? "5 4" : ""}" stroke-opacity=".9"/>` +
      `<text x="${anchor === "start" ? at + 6 : anchor === "end" ? at - 6 : at}" y="${14 + i * 17}" text-anchor="${anchor}" font-size="12.5" font-weight="700" fill="${c}">${label}: ${fmt(v)}</text>`;
  }).join("");
  const axis = [lo, (lo + hi) / 2, hi].map((v) => `<text x="${x(v)}" y="${H - mb + 22}" text-anchor="middle" font-size="12.5" fill="#546B5F">${fmt(v)}</text>`).join("");
  return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="How many of the generated days needed each total amount, with the plan totals marked">
    <defs><linearGradient id="evBar" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#34D399"/><stop offset="1" stop-color="#5EEAD4" stop-opacity=".55"/></linearGradient></defs>
    <line x1="${ml}" x2="${W - mr}" y1="${H - mb}" y2="${H - mb}" stroke="#0D2A1E" stroke-opacity=".18"/>${bars}${lines}${axis}
    <text x="${W / 2}" y="${H - 6}" text-anchor="middle" font-size="12.5" fill="#546B5F">Total portions of the main dishes on a generated day</text></svg>`;
}

export function mountEvents(root) {
  root.innerHTML = SKELETON;
  const q = (s) => root.querySelector(s);
  root.querySelectorAll(".seg").forEach(liquid);
  const V = { types: [], upcoming: [], gan: true, event: "festival", date: null, slot: "lunch", att: 0, option: "forecast", result: null, error: null, busy: false };
  let seq = 0, mounted = false, lastVersion = -1;

  async function load() {
    const mine = ++seq;
    V.busy = true;
    render();
    try {
      const r = await api.post("/events/plan", { date: V.date, meal_slot: V.slot, event: V.event, attendance_change_pct: V.att || null });
      if (mine !== seq) return;
      V.result = r;
      V.error = null;
    } catch (e) { if (mine === seq) V.error = e; }
    if (mine === seq) { V.busy = false; render(); }
  }

  q("#ev-types").addEventListener("click", (e) => { const b = e.target.closest("[data-event]"); if (b) { V.event = b.dataset.event; load(); } });
  q("#ev-slot").addEventListener("click", (e) => { const b = e.target.closest("[data-slot]"); if (b) { V.slot = b.dataset.slot; load(); } });
  q("#ev-date").addEventListener("change", (e) => { if (e.target.value) { V.date = e.target.value; load(); } });
  const att = q("#ev-att");
  const paint = () => {
    const pct = ((Number(att.value) + 40) / 80) * 100;
    att.style.setProperty("--lo", `${Math.min(50, pct)}%`);
    att.style.setProperty("--hi", `${Math.max(50, pct)}%`);
    q("#ev-att-hint").textContent = Number(att.value) ? `${att.value > 0 ? "+" : ""}${att.value}% people` : "No change";
  };
  att.addEventListener("input", paint);
  att.addEventListener("change", () => { V.att = Number(att.value); load(); });
  q("#ev-upcoming").addEventListener("click", (e) => {
    const b = e.target.closest("[data-date]");
    if (!b) return;
    V.date = b.dataset.date;
    V.event = b.dataset.event;
    load();
  });
  q("#ev-options").addEventListener("change", (e) => { if (e.target.name === "ev-option") { V.option = e.target.value; render(); } });

  async function approve(decision) {
    const r = V.result;
    if (!r) return;
    try {
      const adjusted = decision === "approve" ? Object.fromEntries(Object.entries(r.options[V.option]).filter(([id, v]) => v !== r.options.forecast[id])) : {};
      const res = await api.post("/review", { date: r.date, meal_slot: r.meal_slot, decision, overrides: r.approve_with.overrides,
        note: decision === "approve" ? r.approve_with.note : null, adjusted_quantities: adjusted });
      notify(decision === "approve" ? `${r.event_label} plan approved for ${r.meal_slot} on ${shortDate(r.date)}.` : res.message, decision === "approve" ? "ok" : "warn");
      await synced();
    } catch (e) { notify(`${e.message} ${e.fix || ""}`.trim(), "bad"); }
  }
  q("#ev-approve-row").addEventListener("click", (e) => {
    const b = e.target.closest("[data-do]");
    if (!b) return;
    if (b.dataset.do === "open") openPlan(V.result.date, V.result.meal_slot);
    else approve(b.dataset.do);
  });
  q("#ev-many-go").addEventListener("click", async () => {
    const slots = [...root.querySelectorAll(".ev-many-slots input:checked")].map((i) => i.value);
    if (!slots.length) { notify("Tick at least one meal.", "warn"); return; }
    const btn = q("#ev-many-go");
    btn.disabled = true;
    try {
      const r = await api.post("/events/approve", { start: V.date, days: Math.max(1, Math.min(14, Number(q("#ev-days").value) || 1)),
        meal_slots: slots, event: V.event, option: V.option, attendance_change_pct: V.att || null });
      notify(r.message, r.done.length ? "ok" : "warn");
      await synced();
    } catch (e) { notify(`${e.message} ${e.fix || ""}`.trim(), "bad"); }
    btn.disabled = false;
  });

  function render() {
    root.classList.toggle("is-loading", V.busy);
    setHTML(q("#ev-types"), V.types.map((t) => `<button type="button" role="radio" aria-checked="${t.key === V.event}" class="ev-type ${t.key === V.event ? "on" : ""}" data-event="${t.key}">
      <span class="ev-type-ic">${icon(EVENT_ICON[t.key])}</span><span><strong>${esc(t.label)}</strong><small>${esc(t.about)}</small></span></button>`).join(""));
    root.querySelectorAll("[data-slot]").forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.slot === V.slot)));
    const dateIn = q("#ev-date");
    if (V.date && dateIn.value !== V.date && document.activeElement !== dateIn) dateIn.value = V.date;
    if (state.health) { dateIn.min = state.health.first_plan_date; dateIn.max = state.health.last_plan_date; }
    setHTML(q("#ev-upcoming"), V.upcoming.length ? V.upcoming.slice(0, 8).map((u) => `<li><button type="button" class="ev-up ${u.date === V.date && u.event === V.event ? "on" : ""}" data-date="${u.date}" data-event="${u.event}">
      <span class="ev-up-date"><b>${Number(u.date.slice(8))}</b>${esc(new Date(`${u.date}T00:00:00`).toLocaleDateString("en-US", { month: "short" }))}</span>
      <span class="ev-up-what">${esc(u.name)}<small>${esc(u.weekday)}</small></span>${icon(EVENT_ICON[u.event])}</button></li>`).join("")
      : `<li class="feed-empty">Nothing flagged on the calendar in the next months.</li>`);
    q("#ev-gan").innerHTML = V.gan ? `${icon("spark")}The rare event model (a conditional GAN) is trained and generating.` : `${icon("alert")}The rare event model is not trained on this server, so only the forecast side is shown.`;
    setHTML(q("#ev-error"), V.error ? `<div class="banner" style="margin:0 0 16px;width:auto"><strong>${esc(V.error.message)}</strong>${esc(V.error.fix || "")}</div>` : "");

    const r = V.result;
    if (!r) { setHTML(q("#ev-head"), `<div class="skel" style="height:120px"></div>`); return; }
    const kind = planKind(r.review);
    setHTML(q("#ev-head"), `<div class="ev-head-ic">${icon(EVENT_ICON[r.event])}</div><div><p class="ev-head-k">${esc(r.event_label)} · ${esc(cap(r.meal_slot))}, ${esc(r.weekday)} ${esc(shortDate(r.date).replace(/^\w+, /, ""))}</p>
      <h2>${esc(r.plan.headline)}</h2><p>${esc(r.about)}</p></div><div class="ev-head-st">${statusPill(r.review)}${kind ? `<span class="sv-chip">${esc(kind)}</span>` : ""}</div>`);
    const n = r.normal.totals.recommended, ev = r.plan.totals.recommended, g = r.generated.total;
    setHTML(q("#ev-kpis"), [
      ["Normal plan", fmt(n), "portions of the main dishes", ""],
      ["With the event", fmt(ev), `${signed(ev - n)} against normal`, ev > n ? "up" : ev < n ? "down" : ""],
      ["Generated typical day", g ? fmt(g.p50) : "&ndash;", g ? `likely ${fmt(g.p10)} to ${fmt(g.p90)}` : "not available", ""],
      ["Expected attendance", fmt(r.plan.expected_attendance), `${signed(r.plan.expected_attendance - r.normal.expected_attendance)} against normal`, ""],
    ].map(([l, v, c, t]) => `<div class="wi-kpi glass-lite"><span class="wi-kpi-l">${l}</span><span class="wi-kpi-v num">${v}</span><span class="wi-kpi-c ${t}">${c}</span></div>`).join(""));
    q("#ev-gen-note").textContent = r.generated.available && g
      ? `${r.generated.draws} possible days generated for this event. The bars show how many of them needed each total. ${r.verdicts.covered} dish${r.verdicts.covered === 1 ? " is" : "es are"} covered by the forecast, ${r.verdicts.may_run_short} may run short, ${r.verdicts.may_be_left_over} may be left over.`
      : r.generated.note;
    if (setHTML(q("#ev-hist"), histogram(r))) replay(q("#ev-hist"), "fade-in", 600);

    setHTML(q("#ev-dishes"), r.dishes.length ? `<table class="dishes ev-table"><thead><tr><th scope="col">Dish</th><th scope="col">Normal plan</th><th scope="col">Forecast with the event</th>
      <th scope="col">Generated (typical, range)</th><th scope="col">Cook</th><th scope="col">Against the generated days</th></tr></thead><tbody>${r.dishes.map((d) => {
        const [tone, label] = VERDICT[d.verdict];
        const cook = r.options[V.option][d.dish_id];
        return `<tr><td>${esc(d.dish_name)}</td><td>${d.normal_recommended != null ? fmt(d.normal_recommended) : "&ndash;"}</td>
          <td>${fmt(d.recommended)} <small>(${fmt(d.p10)} to ${fmt(d.p90)})</small></td>
          <td>${d.generated ? `${fmt(d.generated.p50)} <small>(${fmt(d.generated.p10)} to ${fmt(d.generated.p90)})</small>` : "&ndash;"}</td>
          <td class="cook">${fmt(cook)}</td><td>${tone ? `<span class="pill ${tone}">${label}</span>` : label}</td></tr>`;
      }).join("")}</tbody></table>` : `<div class="empty"><strong>No main dishes on the menu for this meal.</strong>Pick another meal or day.</div>`);

    const im = r.impact;
    setHTML(q("#ev-ing"), im?.ingredients?.length ? `<p class="dk-panel-note">Against a normal day: ${signed(im.ingredient_totals.change_kg)} kg of ingredients in total. The biggest changes:</p>
      <div class="tablewrap"><table class="wi-table"><thead><tr><th scope="col">Ingredient</th><th scope="col">Normal day</th><th scope="col">With the event</th><th scope="col">Change</th></tr></thead><tbody>${
        im.ingredients.slice(0, 8).map((i) => `<tr><th scope="row">${esc(cap(i.ingredient.replace(/_/g, " ")))}</th><td class="num">${kg(i.before_kg)}</td><td class="num">${kg(i.after_kg)}</td>
          <td class="num wi-chg ${i.change_kg > 0 ? "up" : i.change_kg < 0 ? "down" : ""}">${i.change_kg > 0 ? "+" : ""}${i.change_kg.toFixed(1)} kg</td></tr>`).join("")}</tbody></table></div>`
      : `<p class="dk-panel-note">No recipe data for these dishes.</p>`);

    setHTML(q("#ev-options"), OPTIONS.map(([k, label, about]) => `<label class="ev-option ${V.option === k ? "on" : ""}"><input type="radio" name="ev-option" value="${k}" ${V.option === k ? "checked" : ""}>
      <span><strong>${label}</strong><span class="num">${fmt(r.option_totals[k])} portions</span><small>${about}</small></span></label>`).join(""));
    const approved = r.review?.decision === "approve";
    setHTML(q("#ev-approve-row"), `<button class="btn btn-primary" type="button" data-do="approve">${icon("check")}${approved ? "Approve again with this choice" : "Approve for this meal"}</button>
      <button class="btn btn-danger" type="button" data-do="send_back">${icon("back")}Send back</button>
      ${r.review ? `<button class="btn" type="button" data-do="withdraw">${icon("close")}Withdraw the decision</button>` : ""}
      <button class="btn" type="button" data-do="open">${icon("service")}Open on the Service board</button>`);
  }

  async function start() {
    if (mounted || !state.health) return;
    mounted = true;
    lastVersion = state.dataVersion;
    try {
      const info = await api.get("/events");
      Object.assign(V, { types: info.types, upcoming: info.upcoming, gan: info.gan_available });
      const next = info.upcoming[0];
      V.date = next?.date ?? state.health.default_plan_date;
      V.event = next?.event ?? "festival";
    } catch (e) {
      V.error = e;
      V.date = state.health.default_plan_date;
    }
    takePreset();
    paint();
    load();
  }
  function takePreset() {
    const p = state.eventPreset;
    if (!p) return false;
    state.eventPreset = null;
    V.date = p.date;
    V.event = p.event || V.event;
    return true;
  }
  window.addEventListener("ff:view", (e) => {
    if (e.detail !== "events") return;
    if (!mounted) start(); else if (takePreset()) load();
  });
  subscribe((s) => {
    if (location.hash.slice(1) === "events" && !mounted) start();
    if (mounted && s.dataVersion !== lastVersion) { lastVersion = s.dataVersion; if (V.date) load(); }
  });
}
